import json
from typing import Tuple, Dict

todos = []
next_id = 1

def handle(method: str, path: str, body: bytes) -> Tuple[int, Dict]:
    global todos, next_id

    if method == 'GET' and path == '/todos':
        return (200, todos)

    elif method == 'POST' and path == '/todos':
        try:
            data = json.loads(body.decode())
            text = data.get('text')
            if not text:
                return (400, {'error': 'text is required'})

            todo = {
                'id': next_id,
                'text': text,
                'completed': False
            }
            todos.append(todo)
            next_id += 1
            return (201, todo)
        except json.JSONDecodeError:
            return (400, {'error': 'invalid JSON'})

    elif method == 'PUT' and path.startswith('/todos/'):
        try:
            id = int(path.split('/')[-1])
            todo = next((t for t in todos if t['id'] == id), None)
            if not todo:
                return (404, {'error': 'todo not found'})

            todo['completed'] = not todo['completed']
            return (200, todo)
        except ValueError:
            return (400, {'error': 'invalid id'})

    elif method == 'DELETE' and path.startswith('/todos/'):
        try:
            id = int(path.split('/')[-1])
            todo = next((t for t in todos if t['id'] == id), None)
            if not todo:
                return (404, {'error': 'todo not found'})

            todos = [t for t in todos if t['id'] != id]
            return (200, {'message': 'todo deleted'})
        except ValueError:
            return (400, {'error': 'invalid id'})

    return (404, {'error': 'not found'})

